14	diff --git a/ForecastAccuracy.php b/ForecastAccuracy.php
15	new file mode 100644
16	index 0000000..41e1ad6
17	--- /dev/null
18	+++ b/ForecastAccuracy.php
19	@@ -0,0 +1,192 @@
20	+<?php
21	+
22	+// Compare past forecasts with the sales that followed: MAD, POA, MSE and RMSE by item, category and method
23	+
24	+require(__DIR__ . '/includes/session.php');
25	+include('includes/ForecastFunctions.php');
26	+
27	+$Title = __('Forecast Accuracy');
28	+$ViewTopic = 'Manufacturing';
29	+$BookMark = 'ForecastAccuracy';
30	+include('includes/header.php');
31	+
32	+ForecastPageTitle($Title);
33	+
34	+$Defaults = ForecastGetParameters();
35	+$Bounds = ForecastHistoryBounds();
36	+
37	+if ($Bounds['to'] === null) {
38	+	ForecastNoHistoryNotice();
39	+	include('includes/footer.php');
40	+	exit();
41	+}
42	+
43	+$FromMonth = isset($_POST['FromMonth']) ? ForecastInput($_POST['FromMonth']) : substr($Bounds['from'], 0, 7);
44	+$ToMonth = isset($_POST['ToMonth']) ? ForecastInput($_POST['ToMonth']) : substr($Bounds['to'], 0, 7);
45	+$CategoryID = isset($_POST['CategoryID']) ? ForecastInput($_POST['CategoryID']) : '';
46	+$Location = isset($_POST['Location']) ? ForecastInput($_POST['Location']) : '';
47	+$IncludeSuperseded = isset($_POST['IncludeSuperseded']);
48	+
49	+echo '<form method="post" action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '">';
50	+echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
51	+echo '<fieldset>
52	+		<legend>' . __('Select the forecast periods to measure') . '</legend>
53	+		<field>
54	+			<label for="FromMonth">' . __('From month') . ':</label>
55	+			<input type="month" name="FromMonth" id="FromMonth" required="required" value="' . htmlspecialchars($FromMonth, ENT_QUOTES, 'UTF-8') . '" />
56	+		</field>
57	+		<field>
58	+			<label for="ToMonth">' . __('To month') . ':</label>
59	+			<input type="month" name="ToMonth" id="ToMonth" required="required" value="' . htmlspecialchars($ToMonth, ENT_QUOTES, 'UTF-8') . '" />
60	+		</field>
61	+		<field>
62	+			<label for="CategoryID">' . __('Stock category') . ':</label>
63	+			<select name="CategoryID" id="CategoryID">' . ForecastCategoryOptions($CategoryID, __('Any category')) . '</select>
64	+		</field>
65	+		<field>
66	+			<label for="Location">' . __('Location') . ':</label>
67	+			<select name="Location" id="Location">
68	+				<option value="">' . __('Any location') . '</option>
69	+				<option value="-"' . ($Location == '-' ? ' selected="selected"' : '') . '>' . __('All locations combined') . '</option>' .
70	+				str_replace('<option value=""></option>', '', ForecastLocationOptions($Location, '')) . '
71	+			</select>
72	+		</field>
73	+		<field>
74	+			<label for="IncludeSuperseded">' . __('Include superseded forecasts') . ':</label>
75	+			<input type="checkbox" name="IncludeSuperseded" id="IncludeSuperseded"' . ($IncludeSuperseded ? ' checked="checked"' : '') . ' />
76	+		</field>
77	+	</fieldset>
78	+	<div class="centre">
79	+		<input type="submit" name="Show" value="' . __('Show Accuracy') . '" />
80	+	</div>
81	+	</form>';
82	+echo '<div class="page_help_text">' . __('Only forecast months that now have actual sales in the history held are measured, so extract the latest sales history first. The forecast used is the revised quantity where there is one. MAD is the mean absolute error, MSE the mean squared error and RMSE its square root. POA, the percent of accuracy, is 100 less the total absolute error as a percentage of total actual sales, never below 0.') . '</div>';
83	+
84	+if (isset($_POST['Show'])) {
85	+	$ValidMonths = (preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $FromMonth) && preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $ToMonth));
86	+	if (!$ValidMonths or $FromMonth > $ToMonth) {
87	+		prnMsg(__('Enter the first and last month, the first not after the last'), 'error');
88	+	} else {
89	+		$Where = array(
90	+			"forecastdetails.periodstart >= '" . $FromMonth . "-01'",
91	+			"forecastdetails.periodstart <= '" . $ToMonth . "-01'",
92	+			"forecastdetails.periodstart >= '" . $Bounds['from'] . "'",
93	+			"forecastdetails.periodstart <= '" . $Bounds['to'] . "'",
94	+		);
95	+		if ($CategoryID != '') {
96	+			$Where[] = "stockmaster.categoryid = '" . DB_escape_string($CategoryID) . "'";
97	+		}
98	+		if ($Location == '-') {
99	+			$Where[] = "forecasts.loccode = ''";
100	+		} elseif ($Location != '') {
101	+			$Where[] = "forecasts.loccode = '" . DB_escape_string($Location) . "'";
102	+		}
103	+		if (!$IncludeSuperseded) {
104	+			$Where[] = "forecasts.isactive = 1";
105	+		}
106	+		$Result = DB_query("SELECT forecasts.stockid,
107	+									forecasts.loccode,
108	+									forecasts.method,
109	+									stockmaster.description,
110	+									stockmaster.categoryid,
111	+									" . ForecastEffectiveSQL() . " AS forecastqty,
112	+									COALESCE((SELECT SUM(forecasthistory.quantity)
113	+												FROM forecasthistory
114	+												WHERE forecasthistory.stockid = forecasts.stockid
115	+													AND (forecasts.loccode = '' OR forecasthistory.loccode = forecasts.loccode)
116	+													AND forecasthistory.periodstart = forecastdetails.periodstart), 0) AS actualqty
117	+							FROM forecasts
118	+							INNER JOIN forecastdetails ON forecastdetails.forecastid = forecasts.forecastid
119	+							INNER JOIN stockmaster ON stockmaster.stockid = forecasts.stockid
120	+							WHERE " . implode(' AND ', $Where));
121	+
122	+		$ByItem = array();
123	+		$ByCategory = array();
124	+		$ByMethod = array();
125	+		$Total = ForecastNewAccumulator();
126	+		$Descriptions = array();
127	+		while ($MyRow = DB_fetch_array($Result)) {
128	+			$ItemKey = $MyRow['stockid'] . "\t" . $MyRow['loccode'];
129	+			$Descriptions[$ItemKey] = array($MyRow['stockid'], $MyRow['description'], $MyRow['loccode']);
130	+			if (!isset($ByItem[$ItemKey])) {
131	+				$ByItem[$ItemKey] = ForecastNewAccumulator();
132	+			}
133	+			if (!isset($ByCategory[$MyRow['categoryid']])) {
134	+				$ByCategory[$MyRow['categoryid']] = ForecastNewAccumulator();
135	+			}
136	+			if (!isset($ByMethod[$MyRow['method']])) {
137	+				$ByMethod[$MyRow['method']] = ForecastNewAccumulator();
138	+			}
139	+			ForecastAccumulate($ByItem[$ItemKey], (float) $MyRow['actualqty'], (float) $MyRow['forecastqty']);
140	+			ForecastAccumulate($ByCategory[$MyRow['categoryid']], (float) $MyRow['actualqty'], (float) $MyRow['forecastqty']);
141	+			ForecastAccumulate($ByMethod[$MyRow['method']], (float) $MyRow['actualqty'], (float) $MyRow['forecastqty']);
142	+			ForecastAccumulate($Total, (float) $MyRow['actualqty'], (float) $MyRow['forecastqty']);
143	+		}
144	+
145	+		if ($Total['n'] == 0) {
146	+			prnMsg(__('No forecast months in this range have actual sales to compare with'), 'info');
147	+		} else {
148	+			$Measures = ForecastMeasures($Total);
149	+			$Threshold = $Defaults['lowaccuracy'];
150	+			$Header = '<th>' . __('Months measured') . '</th><th>' . __('MAD') . '</th><th>' . __('POA %') . '</th><th>' . __('MSE') . '</th><th>' . __('RMSE') . '</th>';
151	+			$Row = function ($Accumulator) use ($Threshold) {
152	+				$M = ForecastMeasures($Accumulator);
153	+				return array('<td class="number">' . $M['n'] . '</td>
154	+					<td class="number">' . ForecastFormatQuantity($M['mad']) . '</td>
155	+					<td class="number">' . locale_number_format($M['poa'], 1) . '</td>
156	+					<td class="number">' . ForecastFormatQuantity($M['mse']) . '</td>
157	+					<td class="number">' . ForecastFormatQuantity($M['rmse']) . '</td>', $M['poa'] < $Threshold);
158	+			};
159	+
160	+			echo '<table class="selection">
161	+					<tr><th>' . __('Overall') . '</th>' . $Header . '</tr>';
162	+			list($Cells) = $Row($Total);
163	+			echo '<tr><td></td>' . $Cells . '</tr></table><br />';
164	+
165	+			ksort($ByMethod);
166	+			echo '<table class="selection">
167	+					<tr><th>' . __('Method') . '</th>' . $Header . '</tr>';
168	+			foreach ($ByMethod as $Method => $Accumulator) {
169	+				list($Cells) = $Row($Accumulator);
170	+				echo '<tr class="striped_row"><td>' . $Method . ' - ' . htmlspecialchars(ForecastMethodName($Method), ENT_QUOTES, 'UTF-8') . '</td>' . $Cells . '</tr>';
171	+			}
172	+			echo '</table><br />';
173	+
174	+			ksort($ByCategory);
175	+			echo '<table class="selection">
176	+					<tr><th>' . __('Stock category') . '</th>' . $Header . '</tr>';
177	+			foreach ($ByCategory as $Category => $Accumulator) {
178	+				list($Cells, $Low) = $Row($Accumulator);
179	+				echo '<tr class="striped_row"' . ($Low ? ' style="background-color:#ffd6d6"' : '') . '><td>' . htmlspecialchars($Category, ENT_QUOTES, 'UTF-8') . '</td>' . $Cells . '</tr>';
180	+			}
181	+			echo '</table><br />';
182	+
183	+			uasort($ByItem, function ($A, $B) {
184	+				return ForecastMeasures($A)['poa'] <=> ForecastMeasures($B)['poa'];
185	+			});
186	+			$LowCount = 0;
187	+			foreach ($ByItem as $Accumulator) {
188	+				if (ForecastMeasures($Accumulator)['poa'] < $Threshold) {
189	+					$LowCount++;
190	+				}
191	+			}
192	+			echo '<table class="selection">
193	+					<tr><th colspan="3">' . __('Items') . '</th>' . $Header . '</tr>';
194	+			$Shown = 0;
195	+			foreach ($ByItem as $ItemKey => $Accumulator) {
196	+				if (++$Shown > 500) {
197	+					break;
198	+				}
199	+				list($Cells, $Low) = $Row($Accumulator);
200	+				echo '<tr class="striped_row"' . ($Low ? ' style="background-color:#ffd6d6"' : '') . '>
201	+						<td>' . htmlspecialchars($Descriptions[$ItemKey][0], ENT_QUOTES, 'UTF-8') . '</td>
202	+						<td>' . htmlspecialchars($Descriptions[$ItemKey][1], ENT_QUOTES, 'UTF-8') . '</td>
203	+						<td>' . ($Descriptions[$ItemKey][2] == '' ? __('All') : htmlspecialchars($Descriptions[$ItemKey][2], ENT_QUOTES, 'UTF-8')) . '</td>' . $Cells . '</tr>';
204	+			}
205	+			echo '</table>';
206	+			prnMsg(sprintf(__('%d of %d items have a POA below %s%% (highlighted), lowest first.'), $LowCount, count($ByItem), locale_number_format($Threshold, 0)), $LowCount > 0 ? 'warn' : 'info');
207	+		}
208	+	}
209	+}
210	+
211	+include('includes/footer.php');
