290	diff --git a/ForecastGenerate.php b/ForecastGenerate.php
291	new file mode 100644
292	index 0000000..52efc50
293	--- /dev/null
294	+++ b/ForecastGenerate.php
295	@@ -0,0 +1,204 @@
296	+<?php
297	+
298	+// Generate forecasts for one item, or for every active item of a stock category
299	+
300	+require(__DIR__ . '/includes/session.php');
301	+include('includes/ForecastFunctions.php');
302	+
303	+$Title = __('Generate Forecasts');
304	+$ViewTopic = 'Manufacturing';
305	+$BookMark = 'ForecastGenerate';
306	+include('includes/header.php');
307	+
308	+ForecastPageTitle($Title);
309	+
310	+$BatchSize = 20;
311	+$Defaults = ForecastGetParameters();
312	+$BatchID = 0;
313	+
314	+if (isset($_POST['Generate'])) {
315	+	$InputError = 0;
316	+	$Parameters = ForecastReadParameters($_POST);
317	+	$ScopeType = (isset($_POST['ScopeType']) and $_POST['ScopeType'] == 'category') ? 'category' : 'item';
318	+	$StockID = isset($_POST['StockID']) ? mb_strtoupper(trim(ForecastInput($_POST['StockID']))) : '';
319	+	$CategoryID = isset($_POST['CategoryID']) ? ForecastInput($_POST['CategoryID']) : '';
320	+	$LocCode = isset($_POST['Location']) ? ForecastInput($_POST['Location']) : '';
321	+	$Method = isset($_POST['Method']) ? (int) $_POST['Method'] : 0;
322	+	$Horizon = isset($_POST['Horizon']) ? (int) $_POST['Horizon'] : 0;
323	+
324	+	foreach (ForecastValidateParameters($Parameters) as $Error) {
325	+		prnMsg($Error, 'error');
326	+		$InputError = 1;
327	+	}
328	+	if ($Horizon < 1 or $Horizon > 36) {
329	+		prnMsg(__('The horizon must be between 1 and 36 months'), 'error');
330	+		$InputError = 1;
331	+	}
332	+	if ($Method != 0 and !array_key_exists($Method, ForecastMethods())) {
333	+		prnMsg(__('Unknown forecasting method'), 'error');
334	+		$InputError = 1;
335	+	}
336	+	if ($LocCode != '') {
337	+		$Result = DB_query("SELECT locations.loccode FROM locations
338	+							INNER JOIN locationusers ON locationusers.loccode = locations.loccode
339	+								AND locationusers.userid = '" . DB_escape_string($_SESSION['UserID']) . "' AND locationusers.canview = 1
340	+							WHERE locations.loccode = '" . DB_escape_string($LocCode) . "'");
341	+		if (DB_num_rows($Result) == 0) {
342	+			prnMsg(__('The location is not valid or you may not use it'), 'error');
343	+			$InputError = 1;
344	+		}
345	+	}
346	+	if ($ScopeType == 'item') {
347	+		$Result = DB_query("SELECT stockid FROM stockmaster WHERE stockid = '" . DB_escape_string($StockID) . "'");
348	+		if (DB_num_rows($Result) == 0) {
349	+			prnMsg(__('The item code entered is not an inventory item'), 'error');
350	+			$InputError = 1;
351	+		}
352	+	} else {
353	+		$Result = DB_query("SELECT categoryid FROM stockcategory WHERE categoryid = '" . DB_escape_string($CategoryID) . "'");
354	+		if (DB_num_rows($Result) == 0) {
355	+			prnMsg(__('Select a stock category'), 'error');
356	+			$InputError = 1;
357	+		}
358	+	}
359	+	if (ForecastHistoryBounds()['to'] === null) {
360	+		ForecastNoHistoryNotice();
361	+		$InputError = 1;
362	+	}
363	+
364	+	if ($InputError == 0) {
365	+		set_time_limit(300);
366	+		$BatchID = ForecastCreateBatch($ScopeType, $StockID, $CategoryID, $LocCode, $Method, $Horizon, $Parameters, $_SESSION['UserID']);
367	+		ForecastProcessBatch($BatchID, $BatchSize);
368	+	}
369	+} elseif (isset($_GET['BatchID'])) {
370	+	$BatchID = (int) $_GET['BatchID'];
371	+	set_time_limit(300);
372	+	ForecastProcessBatch($BatchID, $BatchSize);
373	+}
374	+
375	+if ($BatchID > 0) {
376	+	$Result = DB_query("SELECT * FROM forecastbatches WHERE batchid = " . (int) $BatchID);
377	+	$Batch = DB_fetch_array($Result);
378	+	if ($Batch) {
379	+		$Done = $Batch['successcount'] + $Batch['failcount'];
380	+		$Next = $RootPath . '/ForecastGenerate.php?BatchID=' . $BatchID;
381	+		echo '<table class="selection">
382	+				<tr><th colspan="2">' . __('Forecast batch') . ' ' . $BatchID . '</th></tr>
383	+				<tr><td>' . __('Scope') . '</td><td>' . ($Batch['scopetype'] == 'item' ? __('Item') . ' ' . htmlspecialchars($Batch['stockid'], ENT_QUOTES, 'UTF-8') : __('Stock category') . ' ' . htmlspecialchars($Batch['categoryid'], ENT_QUOTES, 'UTF-8')) . '</td></tr>
384	+				<tr><td>' . __('Location') . '</td><td>' . ($Batch['loccode'] == '' ? __('All locations combined') : htmlspecialchars($Batch['loccode'], ENT_QUOTES, 'UTF-8')) . '</td></tr>
385	+				<tr><td>' . __('Method') . '</td><td>' . ($Batch['method'] == 0 ? __('Best fit') . ($Batch['chosenmethod'] > 0 ? ': ' . htmlspecialchars(ForecastMethodName($Batch['chosenmethod']), ENT_QUOTES, 'UTF-8') : '') : htmlspecialchars(ForecastMethodName($Batch['method']), ENT_QUOTES, 'UTF-8')) . '</td></tr>
386	+				<tr><td>' . __('Horizon') . '</td><td>' . $Batch['horizon'] . ' ' . __('months') . '</td></tr>
387	+				<tr><td>' . __('Progress') . '</td><td><progress max="' . max(1, $Batch['totalitems']) . '" value="' . $Done . '"></progress> ' . $Done . ' / ' . $Batch['totalitems'] . '</td></tr>
388	+			</table>';
389	+		if ($Batch['notes'] != '') {
390	+			prnMsg(htmlspecialchars($Batch['notes'], ENT_QUOTES, 'UTF-8'), 'info');
391	+		}
392	+		if ($Batch['status'] == 'running') {
393	+			echo '<div class="centre"><a href="' . $Next . '">' . __('Continue') . '</a></div>
394	+				<script>setTimeout(function () { window.location.href = ' . json_encode(htmlspecialchars_decode($Next)) . '; }, 500);</script>';
395	+		} else {
396	+			prnMsg(sprintf(__('%d successful, %d failed'), $Batch['successcount'], $Batch['failcount']), $Batch['failcount'] > 0 ? 'warn' : 'success');
397	+		}
398	+
399	+		$Result = DB_query("SELECT forecastbatchresults.stockid,
400	+									forecastbatchresults.status,
401	+									forecastbatchresults.message,
402	+									forecastbatchresults.forecastid,
403	+									forecasts.method
404	+							FROM forecastbatchresults
405	+							LEFT JOIN forecasts ON forecasts.forecastid = forecastbatchresults.forecastid
406	+							WHERE forecastbatchresults.batchid = " . (int) $BatchID . "
407	+								AND forecastbatchresults.status <> 'pending'
408	+							ORDER BY forecastbatchresults.status DESC, forecastbatchresults.stockid
409	+							LIMIT 1000");
410	+		if (DB_num_rows($Result) > 0) {
411	+			echo '<br /><table class="selection">
412	+					<tr>
413	+						<th>' . __('Item') . '</th>
414	+						<th>' . __('Result') . '</th>
415	+						<th>' . __('Method') . '</th>
416	+						<th>' . __('Reason') . '</th>
417	+					</tr>';
418	+			while ($MyRow = DB_fetch_array($Result)) {
