1980	+/* Functions shared by the Forecasting module pages.
1981	+
1982	+Conventions
1983	+ - A "series" is a list of monthly quantities, oldest first, no gaps. The last element is the most recent history month.
1984	+ - A period is identified by the first day of its month (Y-m-01).
1985	+ - A location code of '' means "all locations combined".
1986	+ - The effective quantity of a forecast period is the revised quantity when there is one (NULL means none, 0 is a valid
1987	+   revision), otherwise the calculated quantity. Everything that reads forecast quantities uses ForecastEffectiveSQL().
1988	+ - Values passed to these functions are raw values (not already escaped for SQL), see ForecastInput() for posted data.
1989	+ - Sales history comes from stockmoves, see ForecastExtractHistory().
1990	+*/
1991	+
1992	+define('FORECAST_DEMAND_TYPE', 'FC');
1993	+
1994	+/* Raw value of a posted/requested field. session.php escapes and html-encodes every $_POST/$_GET value, the functions
1995	+here escape for themselves so they need the original text */
1996	+function ForecastInput($Value) {
1997	+	return html_entity_decode(stripslashes($Value), ENT_QUOTES, 'UTF-8');
1998	+}
1999	+
2000	+/* ---------------------------------------------------------------------------------------------------------------
2001	+   Dates
2002	+   --------------------------------------------------------------------------------------------------------------- */
2003	+
2004	+function ForecastMonthStart($Date) {
2005	+	return date('Y-m-01', strtotime($Date));
2006	+}
2007	+
2008	+function ForecastAddMonths($Date, $Months) {
2009	+	$DateTime = new DateTime(substr($Date, 0, 7) . '-01');
2010	+	$DateTime->modify(($Months >= 0 ? '+' : '') . (int) $Months . ' month');
2011	+	return $DateTime->format('Y-m-d');
2012	+}
2013	+
2014	+/* number of months from $From to $To, both months included */
2015	+function ForecastMonthsBetween($From, $To) {
2016	+	$FromParts = explode('-', $From);
2017	+	$ToParts = explode('-', $To);
2018	+	return (($ToParts[0] - $FromParts[0]) * 12) + ($ToParts[1] - $FromParts[1]) + 1;
2019	+}
2020	+
2021	+function ForecastMonthLabel($Date) {
2022	+	return MonthAndYearFromSQLDate(substr($Date, 0, 7) . '-01');
2023	+}
2024	+
2025	+/* ---------------------------------------------------------------------------------------------------------------
2026	+   Methods and parameters
2027	+   --------------------------------------------------------------------------------------------------------------- */
2028	+
2029	+function ForecastMethods() {
2030	+	return array(
2031	+		1 => __('Percent over last year'),
