2213	+/* Months of history a method needs before it will produce a forecast */
2214	+function ForecastMinHistory($Method, $Parameters) {
2215	+	switch ((int) $Method) {
2216	+		case 1:
2217	+		case 3:
2218	+		case 6:
2219	+		case 7:
2220	+		case 10:
2221	+		case 11:
2222	+			return 12;
2223	+		case 2:
2224	+			return 24;
2225	+		case 4:
2226	+			return max(4, (int) $Parameters['maperiods']);
2227	+		case 5:
2228	+			return 6;
2229	+		case 8:
2230	+			return max(12, count(ForecastParseWeights($Parameters['flexweights']) ?? array()));
2231	+		case 9:
2232	+			return max(4, count(ForecastParseWeights($Parameters['wmaweights']) ?? array()));
2233	+		case 12:
2234	+			return max(24, 2 * (int) $Parameters['seasonlength']);
2235	+	}
2236	+	return PHP_INT_MAX;
2237	+}
