2239	+/* ---------------------------------------------------------------------------------------------------------------
2240	+   The forecasting methods
2241	+   --------------------------------------------------------------------------------------------------------------- */
2242	+
2243	+/* Forecast $Horizon months after the end of $Series with $Method.
2244	+   Returns array('ok' => true, 'values' => array(...)) with no negative quantities,
2245	+   or array('ok' => false, 'error' => 'reason') - never invented numbers. */
2246	+function ForecastCompute($Method, $Series, $Horizon, $Parameters) {
2247	+	$Method = (int) $Method;
2248	+	$n = count($Series);
2249	+	$Horizon = (int) $Horizon;
2250	+	$Methods = ForecastMethods();
2251	+	if (!isset($Methods[$Method])) {
2252	+		return array('ok' => false, 'error' => __('Unknown forecasting method'));
2253	+	}
2254	+	if ($Horizon < 1) {
2255	+		return array('ok' => false, 'error' => __('The horizon must be at least one month'));
2256	+	}
2257	+	$Required = ForecastMinHistory($Method, $Parameters);
2258	+	if ($n < $Required) {
2259	+		return array('ok' => false, 'error' => sprintf(__('Insufficient history: %s needs %d months and %d are available'), $Methods[$Method], $Required, $n));
2260	+	}
2261	+
2262	+	$Values = array();
2263	+	switch ($Method) {
2264	+		case 1:
2265	+		case 2:
2266	+		case 3:
2267	+			$Factor = 1;
2268	+			if ($Method == 1) {
2269	+				$Factor = 1 + ($Parameters['percent'] / 100);
2270	+			} elseif ($Method == 2) {
2271	+				$LastYear = array_sum(array_slice($Series, $n - 12, 12));
2272	+				$YearBefore = array_sum(array_slice($Series, $n - 24, 12));
2273	+				if ($YearBefore <= 0) {
2274	+					return array('ok' => false, 'error' => __('Sales in the year before last are nil, the growth rate cannot be calculated'));
2275	+				}
2276	+				$Factor = $LastYear / $YearBefore;
2277	+			}
2278	+			for ($h = 1; $h <= $Horizon; $h++) {
2279	+				// the same calendar month of the most recent twelve months of history
2280	+				$Values[] = $Series[$n - 12 + (($h - 1) % 12)] * $Factor;
2281	+			}
2282	+			break;
2283	+
2284	+		case 4:
2285	+			$Last = array_slice($Series, $n - $Parameters['maperiods']);
2286	+			$Average = array_sum($Last) / count($Last);
2287	+			$Values = array_fill(0, $Horizon, $Average);
2288	+			break;
2289	+
2290	+		case 5:
2291	+			// the line through the latest month and the month 'span' months before it
2292	+			$Span = min($Parameters['linearspan'], $n - 1);
2293	+			$Slope = ($Series[$n - 1] - $Series[$n - 1 - $Span]) / $Span;
2294	+			for ($h = 1; $h <= $Horizon; $h++) {
2295	+				$Values[] = $Series[$n - 1] + ($Slope * $h);
2296	+			}
2297	+			break;
2298	+
2299	+		case 6:
2300	+		case 7:
2301	+			$Coefficients = ForecastPolynomialFit($Series, $Method == 6 ? 1 : 2);
2302	+			if ($Coefficients === null) {
2303	+				return array('ok' => false, 'error' => __('The regression could not be solved for this history'));
2304	+			}
2305	+			for ($h = 1; $h <= $Horizon; $h++) {
2306	+				$Values[] = ForecastPolynomialValue($Coefficients, $n + $h, $n);
2307	+			}
2308	+			break;
2309	+
2310	+		case 8:
2311	+			// each month is the sum of the preceding months times the weights, forecast months feed later ones
2312	+			$Weights = ForecastParseWeights($Parameters['flexweights']);
2313	+			$Extended = $Series;
2314	+			for ($h = 1; $h <= $Horizon; $h++) {
2315	+				$Count = count($Extended);
2316	+				$Value = 0;
2317	+				foreach ($Weights as $Lag => $Weight) {
2318	+					$Value += $Weight * $Extended[$Count - 1 - $Lag];
2319	+				}
2320	+				$Value = max(0, $Value);
2321	+				$Extended[] = $Value;
2322	+				$Values[] = $Value;
2323	+			}
2324	+			break;
2325	+
2326	+		case 9:
2327	+			$Weights = ForecastParseWeights($Parameters['wmaweights']);
2328	+			$Total = 0;
2329	+			foreach ($Weights as $Lag => $Weight) {
2330	+				$Total += $Weight * $Series[$n - 1 - $Lag];
2331	+			}
2332	+			$Values = array_fill(0, $Horizon, $Total / array_sum($Weights));
2333	+			break;
2334	+
2335	+		case 10:
2336	+			$Alpha = $Parameters['alpha'];
2337	+			$Level = array_sum(array_slice($Series, 0, 3)) / 3;
2338	+			foreach ($Series as $Actual) {
2339	+				$Level = ($Alpha * $Actual) + ((1 - $Alpha) * $Level);
2340	+			}
2341	+			$Values = array_fill(0, $Horizon, $Level);
2342	+			break;
2343	+
2344	+		case 11:
2345	+			$Alpha = $Parameters['alpha'];
2346	+			$Beta = $Parameters['beta'];
2347	+			$Level = $Series[0];
2348	+			$Trend = ($Series[3] - $Series[0]) / 3;
2349	+			for ($t = 1; $t < $n; $t++) {
2350	+				$PreviousLevel = $Level;
2351	+				$Level = ($Alpha * $Series[$t]) + ((1 - $Alpha) * ($Level + $Trend));
2352	+				$Trend = ($Beta * ($Level - $PreviousLevel)) + ((1 - $Beta) * $Trend);
2353	+			}
2354	+			for ($h = 1; $h <= $Horizon; $h++) {
2355	+				$Values[] = $Level + ($Trend * $h);
2356	+			}
2357	+			break;
2358	+
2359	+		case 12:
2360	+			// additive Holt-Winters
2361	+			$Alpha = $Parameters['alpha'];
2362	+			$Beta = $Parameters['beta'];
2363	+			$Gamma = $Parameters['gamma'];
2364	+			$L = $Parameters['seasonlength'];
2365	+			$FirstSeason = array_sum(array_slice($Series, 0, $L)) / $L;
2366	+			$SecondSeason = array_sum(array_slice($Series, $L, $L)) / $L;
2367	+			$Level = $FirstSeason;
2368	+			$Trend = ($SecondSeason - $FirstSeason) / $L;
2369	+			$Season = array();
2370	+			for ($i = 0; $i < $L; $i++) {
2371	+				$Season[$i] = $Series[$i] - $FirstSeason;
2372	+			}
2373	+			for ($t = $L; $t < $n; $t++) {
2374	+				$Index = $t % $L;
2375	+				$PreviousLevel = $Level;
2376	+				$Level = ($Alpha * ($Series[$t] - $Season[$Index])) + ((1 - $Alpha) * ($Level + $Trend));
2377	+				$Trend = ($Beta * ($Level - $PreviousLevel)) + ((1 - $Beta) * $Trend);
2378	+				$Season[$Index] = ($Gamma * ($Series[$t] - $Level)) + ((1 - $Gamma) * $Season[$Index]);
2379	+			}
2380	+			for ($h = 1; $h <= $Horizon; $h++) {
2381	+				$Values[] = $Level + ($Trend * $h) + $Season[($n - 1 + $h) % $L];
2382	+			}
2383	+			break;
2384	+	}
2385	+
2386	+	foreach ($Values as $Key => $Value) {
2387	+		if (!is_finite($Value)) {
2388	+			return array('ok' => false, 'error' => __('The calculation did not produce a usable number'));
2389	+		}
2390	+		$Values[$Key] = round(max(0, $Value), 2);
2391	+	}
2392	+	return array('ok' => true, 'values' => $Values);
2393	+}
