2395	+/* Least squares polynomial of $Degree (1 or 2) through the series at t = 1..n. Time is centred to keep the
2396	+   normal equations well conditioned. Returns the coefficients, lowest power first, or null. */
2397	+function ForecastPolynomialFit($Series, $Degree) {
2398	+	$n = count($Series);
2399	+	$Size = $Degree + 1;
2400	+	$Matrix = array();
2401	+	for ($r = 0; $r < $Size; $r++) {
2402	+		$Matrix[$r] = array_fill(0, $Size + 1, 0.0);
2403	+	}
2404	+	for ($t = 1; $t <= $n; $t++) {
2405	+		$x = $t - (($n + 1) / 2);
2406	+		for ($r = 0; $r < $Size; $r++) {
2407	+			for ($c = 0; $c < $Size; $c++) {
2408	+				$Matrix[$r][$c] += pow($x, $r + $c);
2409	+			}
2410	+			$Matrix[$r][$Size] += pow($x, $r) * $Series[$t - 1];
2411	+		}
2412	+	}
2413	+	// Gaussian elimination with partial pivoting
2414	+	for ($i = 0; $i < $Size; $i++) {
2415	+		$Pivot = $i;
2416	+		for ($r = $i + 1; $r < $Size; $r++) {
2417	+			if (abs($Matrix[$r][$i]) > abs($Matrix[$Pivot][$i])) {
2418	+				$Pivot = $r;
2419	+			}
2420	+		}
2421	+		if (abs($Matrix[$Pivot][$i]) < 1e-12) {
2422	+			return null;
2423	+		}
2424	+		$Swap = $Matrix[$i];
2425	+		$Matrix[$i] = $Matrix[$Pivot];
2426	+		$Matrix[$Pivot] = $Swap;
2427	+		for ($r = $i + 1; $r < $Size; $r++) {
2428	+			$Ratio = $Matrix[$r][$i] / $Matrix[$i][$i];
2429	+			for ($c = $i; $c <= $Size; $c++) {
2430	+				$Matrix[$r][$c] -= $Ratio * $Matrix[$i][$c];
2431	+			}
2432	+		}
2433	+	}
2434	+	$Coefficients = array_fill(0, $Size, 0.0);
2435	+	for ($i = $Size - 1; $i >= 0; $i--) {
2436	+		$Sum = $Matrix[$i][$Size];
2437	+		for ($c = $i + 1; $c < $Size; $c++) {
2438	+			$Sum -= $Matrix[$i][$c] * $Coefficients[$c];
2439	+		}
2440	+		$Coefficients[$i] = $Sum / $Matrix[$i][$i];
2441	+	}
2442	+	return $Coefficients;
2443	+}
2444	+
2445	+function ForecastPolynomialValue($Coefficients, $t, $n) {
2446	+	$x = $t - (($n + 1) / 2);
2447	+	$Value = 0;
2448	+	foreach ($Coefficients as $Power => $Coefficient) {
2449	+		$Value += $Coefficient * pow($x, $Power);
2450	+	}
2451	+	return $Value;
2452	+}
