2454	+/* ---------------------------------------------------------------------------------------------------------------
2455	+   Accuracy measures
2456	+   --------------------------------------------------------------------------------------------------------------- */
2457	+
2458	+function ForecastNewAccumulator() {
2459	+	return array('n' => 0, 'sumabs' => 0.0, 'sumsq' => 0.0, 'sumactual' => 0.0, 'sumforecast' => 0.0);
