2462	+function ForecastAccumulate(&$Accumulator, $Actual, $Forecast) {
2463	+	$Error = $Actual - $Forecast;
2464	+	$Accumulator['n']++;
2465	+	$Accumulator['sumabs'] += abs($Error);
2466	+	$Accumulator['sumsq'] += $Error * $Error;
2467	+	$Accumulator['sumactual'] += $Actual;
2468	+	$Accumulator['sumforecast'] += $Forecast;
