2471	+/* MAD, MSE, RMSE and POA from an accumulator.
2472	+   POA (percent of accuracy) = 100 x (1 - sum of absolute errors / sum of actual sales), never below 0.
2473	+   When there were no actual sales it is 100 if nothing was forecast either, otherwise 0. */
2474	+function ForecastMeasures($Accumulator) {
2475	+	if ($Accumulator['n'] == 0) {
2476	+		return array('n' => 0, 'mad' => null, 'mse' => null, 'rmse' => null, 'poa' => null);
2477	+	}
2478	+	$Measures = array('n' => $Accumulator['n']);
2479	+	$Measures['mad'] = $Accumulator['sumabs'] / $Accumulator['n'];
2480	+	$Measures['mse'] = $Accumulator['sumsq'] / $Accumulator['n'];
2481	+	$Measures['rmse'] = sqrt($Measures['mse']);
2482	+	if ($Accumulator['sumactual'] > 0) {
2483	+		$Measures['poa'] = max(0, 100 * (1 - ($Accumulator['sumabs'] / $Accumulator['sumactual'])));
2484	+	} else {
2485	+		$Measures['poa'] = ($Accumulator['sumabs'] == 0) ? 100 : 0;
2486	+	}
2487	+	return $Measures;
2488	+}
