1845	+/** Method id => translated name */
1846	+function fcMethodNames() {
1847	+	return array(
1848	+		1 => __('Percent over last year'),
1849	+		2 => __('Calculated percent over last year'),
1850	+		3 => __('Last year to this year'),
1851	+		4 => __('Moving average'),
1852	+		5 => __('Linear approximation'),
1853	+		6 => __('Least squares regression'),
1854	+		7 => __('Second degree approximation'),
1855	+		8 => __('Flexible method'),
1856	+		9 => __('Weighted moving average'),
1857	+		10 => __('Simple exponential smoothing'),
1858	+		11 => __('Holt double exponential smoothing'),
1859	+		12 => __('Holt-Winters seasonal smoothing')
1860	+	);
1861	+}
