1922	+/** Validates the parameters, returns a list of translated problems (empty when fine) */
1923	+function fcValidateParameters($Parameters) {
1924	+	$Problems = array();
1925	+	foreach (array('alpha' => __('Alpha'), 'beta' => __('Beta'), 'gamma' => __('Gamma')) as $Key => $Label) {
1926	+		if (!is_numeric($Parameters[$Key]) or $Parameters[$Key] < 0.1 or $Parameters[$Key] > 0.9) {
1927	+			$Problems[] = $Label . ': ' . __('must be a number from 0.1 to 0.9');
1928	+		}
1929	+	}
1930	+	if (!ctype_digit((string) $Parameters['seasonlength']) or $Parameters['seasonlength'] < 2 or $Parameters['seasonlength'] > 24) {
1931	+		$Problems[] = __('Season length') . ': ' . __('must be a whole number from 2 to 24');
1932	+	}
1933	+	if (!ctype_digit((string) $Parameters['maperiods']) or $Parameters['maperiods'] < 2 or $Parameters['maperiods'] > 12) {
1934	+		$Problems[] = __('Moving average periods') . ': ' . __('must be a whole number from 2 to 12');
1935	+	}
1936	+	if (!ctype_digit((string) $Parameters['holdoutmonths']) or $Parameters['holdoutmonths'] < 1 or $Parameters['holdoutmonths'] > 12) {
1937	+		$Problems[] = __('Hold-out months') . ': ' . __('must be a whole number from 1 to 12');
1938	+	}
1939	+	if (!ctype_digit((string) $Parameters['defaulthorizon']) or $Parameters['defaulthorizon'] < 1 or $Parameters['defaulthorizon'] > 36) {
1940	+		$Problems[] = __('Default horizon') . ': ' . __('must be a whole number from 1 to 36');
1941	+	}
1942	+	if (!is_numeric($Parameters['growthpercent']) or $Parameters['growthpercent'] <= -100) {
1943	+		$Problems[] = __('Growth percent') . ': ' . __('must be a number greater than -100');
1944	+	}
1945	+	foreach (array('flexibleweights' => __('Flexible method weights'), 'wmaweights' => __('Weighted moving average weights')) as $Key => $Label) {
1946	+		$Weights = fcMethodParameters(array_merge(fcDefaultParameters(), array($Key => $Parameters[$Key])))[$Key];
1947	+		if (count($Weights) < 1 or count($Weights) > 12 or in_array(null, $Weights, true) or min($Weights) < 0 or array_sum($Weights) <= 0) {
1948	+			$Problems[] = $Label . ': ' . __('must be a list of 1 to 12 non-negative numbers separated by commas, most recent period first');
1949	+		}
1950	+	}
1951	+	if (!ctype_digit((string) $Parameters['poathreshold']) or $Parameters['poathreshold'] > 100) {
1952	+		$Problems[] = __('Accuracy tolerance') . ': ' . __('must be a whole number from 0 to 100');
1953	+	}
1954	+	if (!ctype_digit((string) $Parameters['variancethreshold'])) {
1955	+		$Problems[] = __('Variance highlight') . ': ' . __('must be a whole number');
1956	+	}
1957	+	if (!ctype_digit((string) $Parameters['batchsize']) or $Parameters['batchsize'] < 1 or $Parameters['batchsize'] > 200) {
1958	+		$Problems[] = __('Batch size') . ': ' . __('must be a whole number from 1 to 200');
1959	+	}
1960	+	return $Problems;
1961	+}
