1963	+/** The parameters a method really used, as text kept with the forecast */
1964	+function fcParametersUsed($Method, $Parameters) {
1965	+	switch ($Method) {
1966	+		case 1:
1967	+			return 'percent=' . $Parameters['growthpercent'];
1968	+		case 4:
1969	+			return 'periods=' . $Parameters['maperiods'];
1970	+		case 8:
1971	+			return 'weights=' . $Parameters['flexibleweights'];
1972	+		case 9:
