1976	+		case 11:
1977	+			return 'alpha=' . $Parameters['alpha'] . ';beta=' . $Parameters['beta'];
1978	+		case 12:
1979	+			return 'alpha=' . $Parameters['alpha'] . ';beta=' . $Parameters['beta'] . ';gamma=' . $Parameters['gamma'] . ';season=' . $Parameters['seasonlength'];
1980	+	}
1981	+	return '';
