1987	+
1988	+/** First day of the month of an ISO date (or YYYY-MM), moved by $Months months */
1989	+function fcMonthAdd($Date, $Months = 0) {
1990	+	$Year = (int) substr($Date, 0, 4);
1991	+	$Month = (int) substr($Date, 5, 2) - 1 + $Months;
1992	+	$Year += (int) floor($Month / 12);
1993	+	$Month = $Month % 12;
1994	+	if ($Month < 0) {
1995	+		$Month += 12;
1996	+	}
1997	+	return sprintf('%04d-%02d-01', $Year, $Month + 1);
1998	+}
1999	+
2000	+/** Number of months from $From to $To (both first of month) */
2001	+function fcMonthDiff($From, $To) {
2002	+	return ((int) substr($To, 0, 4) - (int) substr($From, 0, 4)) * 12 + (int) substr($To, 5, 2) - (int) substr($From, 5, 2);
2003	+}
2004	+
2005	+/** Is the text a YYYY-MM month (as sent by the month input) */
2006	+function fcIsMonth($Text) {
2007	+	return preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $Text) === 1;
2008	+}
2009	+
2010	+/** The last month that is complete today, first of month */
2011	+function fcLastCompleteMonth() {
2012	+	return fcMonthAdd(date('Y-m-01'), -1);
2013	+}
