2020	+/* Sales history                                                                                              */
2021	+/* ---------------------------------------------------------------------------------------------------------- */
2022	+
2023	+/** Range and size of the history held: array(from, to, items, months, rows) - from/to null when empty */
2024	+function fcHistoryRange() {
2025	+	$Result = DB_query("SELECT MIN(periodstart) AS firstmonth,
2026	+							MAX(periodstart) AS lastmonth,
2027	+							COUNT(DISTINCT stockid) AS items,
2028	+							COUNT(DISTINCT periodstart) AS months,
2029	+							COUNT(*) AS historyrows
2030	+						FROM fcsaleshistory");
2031	+	$MyRow = DB_fetch_array($Result);
2032	+	/* the range the user extracted is kept in fcparameters: months at the end of the range in which nothing
2033	+	   was sold are still part of the history (as zero sales), they just have no rows */
2034	+	$Result = DB_query("SELECT parametername, parametervalue FROM fcparameters
2035	+						WHERE parametername IN ('historyfrom', 'historyto')");
2036	+	$Held = array();
2037	+	while ($HeldRow = DB_fetch_array($Result)) {
2038	+		$Held[$HeldRow['parametername']] = $HeldRow['parametervalue'];
2039	+	}
2040	+	if (isset($Held['historyfrom']) and isset($Held['historyto']) and $MyRow['firstmonth'] !== null) {
2041	+		$MyRow['firstmonth'] = $Held['historyfrom'];
2042	+		$MyRow['lastmonth'] = $Held['historyto'];
2043	+		$MyRow['months'] = fcMonthDiff($Held['historyfrom'], $Held['historyto']) + 1;
2044	+	} elseif ($MyRow['firstmonth'] === null) {
2045	+		$MyRow['months'] = 0;
2046	+	}
2047	+	return array(
2048	+		'from' => $MyRow['firstmonth'],
2049	+		'to' => $MyRow['lastmonth'],
2050	+		'items' => (int) $MyRow['items'],
2051	+		'months' => (int) $MyRow['months'],
2052	+		'rows' => (int) $MyRow['historyrows']
2053	+	);
2054	+}
2055	+
2056	+/**
2057	+ * Replaces the held history of the months from $FromMonth to $ToMonth (first of month dates, inclusive) with the
2058	+ * net quantities sold - invoices (type 10) less credit notes (type 11) from stockmoves - the same movements the
2059	+ * stock usage and sales inquiries are built on. Returns the number of history rows written.
2060	+ */
2061	+function fcExtractSalesHistory($FromMonth, $ToMonth) {
2062	+	$FromDate = $FromMonth;
2063	+	$ToDate = date('Y-m-t', strtotime($ToMonth));
2064	+
2065	+	DB_Txn_Begin();
2066	+	DB_query("DELETE FROM fcsaleshistory
2067	+				WHERE periodstart >= '" . $FromDate . "'
2068	+				AND periodstart <= '" . $ToDate . "'", '', '', true);
2069	+	/* sales are negative stock movements: invoices (10) are negative, credit notes (11) positive,
2070	+	   so the net quantity sold is the negated sum. hidemovt=1 movements are not shown by the sales reports. */
2071	+	DB_query("INSERT INTO fcsaleshistory (stockid,
2072	+										loccode,
2073	+										periodstart,
2074	+										debtortype,
2075	+										area,
2076	+										salesman,
2077	+										quantity)
2078	+				SELECT stockmoves.stockid,
2079	+					stockmoves.loccode,
2080	+					DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
2081	+					COALESCE(debtorsmaster.typeid, 0),
2082	+					COALESCE(custbranch.area, ''),
2083	+					COALESCE(custbranch.salesman, ''),
2084	+					-SUM(stockmoves.qty)
2085	+				FROM stockmoves
2086	+				LEFT JOIN debtorsmaster ON debtorsmaster.debtorno = stockmoves.debtorno
2087	+				LEFT JOIN custbranch ON custbranch.debtorno = stockmoves.debtorno
2088	+					AND custbranch.branchcode = stockmoves.branchcode
2089	+				WHERE stockmoves.type IN (10, 11)
2090	+				AND stockmoves.hidemovt = 0
2091	+				AND stockmoves.trandate >= '" . $FromDate . "'
2092	+				AND stockmoves.trandate <= '" . $ToDate . "'
2093	+				GROUP BY stockmoves.stockid,
2094	+					stockmoves.loccode,
2095	+					DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
2096	+					COALESCE(debtorsmaster.typeid, 0),
2097	+					COALESCE(custbranch.area, ''),
2098	+					COALESCE(custbranch.salesman, '')", '', '', true);
2099	+	/* the range now held: the extracted range joined to what was held before (the page only allows ranges that
2100	+	   overlap or touch the held one, so there is never a gap that would read as zero sales) */
2101	+	$Held = fcHistoryRange();
2102	+	$NewFrom = ($Held['from'] === null or $Held['from'] > $FromMonth) ? $FromMonth : $Held['from'];
2103	+	$NewTo = ($Held['to'] === null or $Held['to'] < $ToMonth) ? $ToMonth : $Held['to'];
2104	+	foreach (array('historyfrom' => $NewFrom, 'historyto' => $NewTo) as $Name => $Value) {
2105	+		DB_query("REPLACE INTO fcparameters (parametername, parametervalue) VALUES ('" . $Name . "', '" . $Value . "')", '', '', true);
2106	+	}
2107	+	DB_Txn_Commit();
2108	+	$Result = DB_query("SELECT COUNT(*) FROM fcsaleshistory
2109	+						WHERE periodstart >= '" . $FromDate . "'
2110	+						AND periodstart <= '" . $ToDate . "'");
2111	+	$MyRow = DB_fetch_row($Result);
2112	+	return (int) $MyRow[0];
2113	+}
2114	+
2115	+/**
2116	+ * The monthly net quantity series of an item (location 'ALL' = all locations) over the held history.
2117	+ * Returns array('values' => list oldest first, 'first' => first month, 'last' => last month) where the series
2118	+ * starts with the first month the item sold anything - earlier months are not history of the item, so they are
2119	+ * not padded with made-up zeros. Months without sales after that are real zeros.
2120	+ */
2121	+function fcItemSeries($StockID, $Location, $RangeFrom = null, $RangeTo = null) {
2122	+	if ($RangeFrom === null) {
2123	+		$Range = fcHistoryRange();
2124	+		$RangeFrom = $Range['from'];
2125	+		$RangeTo = $Range['to'];
2126	+	}
2127	+	if ($RangeFrom === null) {
2128	+		return array('values' => array(), 'first' => null, 'last' => null);
2129	+	}
2130	+	$SQL = "SELECT periodstart, SUM(quantity) AS qty
2131	+			FROM fcsaleshistory
2132	+			WHERE stockid = '" . $StockID . "'
2133	+			AND periodstart >= '" . $RangeFrom . "'
2134	+			AND periodstart <= '" . $RangeTo . "'" .
2135	+			($Location != FC_ALL_LOCATIONS ? " AND loccode = '" . $Location . "'" : '') . "
2136	+			GROUP BY periodstart
