+/* ---------------------------------------------------------------------------------------------------------- */
+/* Dates                                                                                                      */
+/* ---------------------------------------------------------------------------------------------------------- */
+
+/** First day of the month of an ISO date (or YYYY-MM), moved by $Months months */
+function fcMonthAdd($Date, $Months = 0) {
+	$Year = (int) substr($Date, 0, 4);
+	$Month = (int) substr($Date, 5, 2) - 1 + $Months;
+	$Year += (int) floor($Month / 12);
+	$Month = $Month % 12;
+	if ($Month < 0) {
+		$Month += 12;
+	}
+	return sprintf('%04d-%02d-01', $Year, $Month + 1);
+}
+
+/** Number of months from $From to $To (both first of month) */
+function fcMonthDiff($From, $To) {
+	return ((int) substr($To, 0, 4) - (int) substr($From, 0, 4)) * 12 + (int) substr($To, 5, 2) - (int) substr($From, 5, 2);
+}
+
+/** Is the text a YYYY-MM month (as sent by the month input) */
+function fcIsMonth($Text) {
+	return preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $Text) === 1;
+}
+
+/** The last month that is complete today, first of month */
+function fcLastCompleteMonth() {
+	return fcMonthAdd(date('Y-m-01'), -1);
+}
+
+function fcMonthLabel($Date) {
+	return substr($Date, 0, 7);
+}
