+/* ---------------------------------------------------------------------------------------------------------- */
+/* Sales history                                                                                              */
+/* ---------------------------------------------------------------------------------------------------------- */
+
+/** Range and size of the history held: array(from, to, items, months, rows) - from/to null when empty */
+function fcHistoryRange() {
+	$Result = DB_query("SELECT MIN(periodstart) AS firstmonth,
+							MAX(periodstart) AS lastmonth,
+							COUNT(DISTINCT stockid) AS items,
+							COUNT(DISTINCT periodstart) AS months,
+							COUNT(*) AS historyrows
+						FROM fcsaleshistory");
+	$MyRow = DB_fetch_array($Result);
+	/* the range the user extracted is kept in fcparameters: months at the end of the range in which nothing
+	   was sold are still part of the history (as zero sales), they just have no rows */
+	$Result = DB_query("SELECT parametername, parametervalue FROM fcparameters
+						WHERE parametername IN ('historyfrom', 'historyto')");
+	$Held = array();
+	while ($HeldRow = DB_fetch_array($Result)) {
+		$Held[$HeldRow['parametername']] = $HeldRow['parametervalue'];
+	}
+	if (isset($Held['historyfrom']) and isset($Held['historyto']) and $MyRow['firstmonth'] !== null) {
+		$MyRow['firstmonth'] = $Held['historyfrom'];
+		$MyRow['lastmonth'] = $Held['historyto'];
+		$MyRow['months'] = fcMonthDiff($Held['historyfrom'], $Held['historyto']) + 1;
+	} elseif ($MyRow['firstmonth'] === null) {
+		$MyRow['months'] = 0;
+	}
+	return array(
+		'from' => $MyRow['firstmonth'],
+		'to' => $MyRow['lastmonth'],
+		'items' => (int) $MyRow['items'],
+		'months' => (int) $MyRow['months'],
+		'rows' => (int) $MyRow['historyrows']
+	);
+}
+
+/**
+ * Replaces the held history of the months from $FromMonth to $ToMonth (first of month dates, inclusive) with the
+ * net quantities sold - invoices (type 10) less credit notes (type 11) from stockmoves - the same movements the
+ * stock usage and sales inquiries are built on. Returns the number of history rows written.
+ */
+function fcExtractSalesHistory($FromMonth, $ToMonth) {
+	$FromDate = $FromMonth;
+	$ToDate = date('Y-m-t', strtotime($ToMonth));
+
+	DB_Txn_Begin();
+	DB_query("DELETE FROM fcsaleshistory
+				WHERE periodstart >= '" . $FromDate . "'
+				AND periodstart <= '" . $ToDate . "'", '', '', true);
+	/* sales are negative stock movements: invoices (10) are negative, credit notes (11) positive,
+	   so the net quantity sold is the negated sum. hidemovt=1 movements are not shown by the sales reports. */
+	DB_query("INSERT INTO fcsaleshistory (stockid,
+										loccode,
+										periodstart,
+										debtortype,
+										area,
+										salesman,
+										quantity)
+				SELECT stockmoves.stockid,
+					stockmoves.loccode,
+					DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
+					COALESCE(debtorsmaster.typeid, 0),
+					COALESCE(custbranch.area, ''),
+					COALESCE(custbranch.salesman, ''),
+					-SUM(stockmoves.qty)
+				FROM stockmoves
+				LEFT JOIN debtorsmaster ON debtorsmaster.debtorno = stockmoves.debtorno
+				LEFT JOIN custbranch ON custbranch.debtorno = stockmoves.debtorno
+					AND custbranch.branchcode = stockmoves.branchcode
+				WHERE stockmoves.type IN (10, 11)
+				AND stockmoves.hidemovt = 0
+				AND stockmoves.trandate >= '" . $FromDate . "'
+				AND stockmoves.trandate <= '" . $ToDate . "'
+				GROUP BY stockmoves.stockid,
+					stockmoves.loccode,
+					DATE_FORMAT(stockmoves.trandate, '%Y-%m-01'),
+					COALESCE(debtorsmaster.typeid, 0),
+					COALESCE(custbranch.area, ''),
+					COALESCE(custbranch.salesman, '')", '', '', true);
+	/* the range now held: the extracted range joined to what was held before (the page only allows ranges that
+	   overlap or touch the held one, so there is never a gap that would read as zero sales) */
+	$Held = fcHistoryRange();
+	$NewFrom = ($Held['from'] === null or $Held['from'] > $FromMonth) ? $FromMonth : $Held['from'];
+	$NewTo = ($Held['to'] === null or $Held['to'] < $ToMonth) ? $ToMonth : $Held['to'];
+	foreach (array('historyfrom' => $NewFrom, 'historyto' => $NewTo) as $Name => $Value) {
+		DB_query("REPLACE INTO fcparameters (parametername, parametervalue) VALUES ('" . $Name . "', '" . $Value . "')", '', '', true);
+	}
+	DB_Txn_Commit();
+	$Result = DB_query("SELECT COUNT(*) FROM fcsaleshistory
+						WHERE periodstart >= '" . $FromDate . "'
+						AND periodstart <= '" . $ToDate . "'");
+	$MyRow = DB_fetch_row($Result);
+	return (int) $MyRow[0];
+}
