+/**
+ * The monthly net quantity series of an item (location 'ALL' = all locations) over the held history.
+ * Returns array('values' => list oldest first, 'first' => first month, 'last' => last month) where the series
+ * starts with the first month the item sold anything - earlier months are not history of the item, so they are
+ * not padded with made-up zeros. Months without sales after that are real zeros.
+ */
+function fcItemSeries($StockID, $Location, $RangeFrom = null, $RangeTo = null) {
+	if ($RangeFrom === null) {
+		$Range = fcHistoryRange();
+		$RangeFrom = $Range['from'];
+		$RangeTo = $Range['to'];
+	}
+	if ($RangeFrom === null) {
+		return array('values' => array(), 'first' => null, 'last' => null);
+	}
+	$SQL = "SELECT periodstart, SUM(quantity) AS qty
+			FROM fcsaleshistory
+			WHERE stockid = '" . $StockID . "'
+			AND periodstart >= '" . $RangeFrom . "'
+			AND periodstart <= '" . $RangeTo . "'" .
+			($Location != FC_ALL_LOCATIONS ? " AND loccode = '" . $Location . "'" : '') . "
+			GROUP BY periodstart
+			ORDER BY periodstart";
+	$Result = DB_query($SQL);
+	$ByMonth = array();
+	while ($MyRow = DB_fetch_array($Result)) {
+		$ByMonth[$MyRow['periodstart']] = (float) $MyRow['qty'];
+	}
+	return fcBuildSeries($ByMonth, $RangeFrom, $RangeTo);
+}
+
+/** Zero fills a month => quantity map from its first month with data to $RangeTo */
+function fcBuildSeries($ByMonth, $RangeFrom, $RangeTo) {
+	if (count($ByMonth) == 0) {
+		return array('values' => array(), 'first' => null, 'last' => null);
+	}
+	$First = min(array_keys($ByMonth));
+	$Values = array();
+	for ($Month = $First; $Month <= $RangeTo; $Month = fcMonthAdd($Month, 1)) {
+		$Values[] = $ByMonth[$Month] ?? 0.0;
+	}
+	return array('values' => $Values, 'first' => $First, 'last' => $RangeTo);
+}
+
+/** Quantity sold per month for a list of month dates, for an item and location (actuals for comparisons) */
+function fcActuals($StockID, $Location, $FromMonth, $ToMonth) {
+	$SQL = "SELECT periodstart, SUM(quantity) AS qty
+			FROM fcsaleshistory
+			WHERE stockid = '" . $StockID . "'
+			AND periodstart >= '" . $FromMonth . "'
+			AND periodstart <= '" . $ToMonth . "'" .
+			($Location != FC_ALL_LOCATIONS ? " AND loccode = '" . $Location . "'" : '') . "
+			GROUP BY periodstart";
+	$Result = DB_query($SQL);
+	$Actuals = array();
+	while ($MyRow = DB_fetch_array($Result)) {
+		$Actuals[$MyRow['periodstart']] = (float) $MyRow['qty'];
+	}
+	return $Actuals;
+}
