+function fcFail($Reason) {
+	return array('ok' => false, 'values' => array(), 'error' => $Reason);
+}
+
+function fcOk($Values) {
+	$Clean = array();
+	foreach ($Values as $Value) {
+		/* no negative forecast quantities */
+		$Clean[] = max(0, round($Value, 2));
+	}
+	return array('ok' => true, 'values' => $Clean, 'error' => '');
+}
+
+/** Solves the 3x3 system A x = b by Gauss elimination, null if singular */
+function fcSolve3($A, $B) {
+	for ($Col = 0; $Col < 3; $Col++) {
+		$Pivot = $Col;
+		for ($Row = $Col + 1; $Row < 3; $Row++) {
+			if (abs($A[$Row][$Col]) > abs($A[$Pivot][$Col])) {
+				$Pivot = $Row;
+			}
+		}
+		if (abs($A[$Pivot][$Col]) < 1e-12) {
+			return null;
+		}
+		list($A[$Col], $A[$Pivot]) = array($A[$Pivot], $A[$Col]);
+		list($B[$Col], $B[$Pivot]) = array($B[$Pivot], $B[$Col]);
+		for ($Row = $Col + 1; $Row < 3; $Row++) {
+			$Factor = $A[$Row][$Col] / $A[$Col][$Col];
+			for ($k = $Col; $k < 3; $k++) {
+				$A[$Row][$k] -= $Factor * $A[$Col][$k];
+			}
+			$B[$Row] -= $Factor * $B[$Col];
+		}
+	}
+	$X = array(0, 0, 0);
+	for ($Row = 2; $Row >= 0; $Row--) {
+		$Sum = $B[$Row];
+		for ($k = $Row + 1; $k < 3; $k++) {
+			$Sum -= $A[$Row][$k] * $X[$k];
+		}
+		$X[$Row] = $Sum / $A[$Row][$Row];
+	}
+	return $X;
+}
